(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12 + Math.sin((x+y)*0.008+t*0.15)*8;
  const w1y = Math.cos(y*0.02-t*0.28)*16 + Math.sin(x*0.016+t*0.33)*11 + Math.cos((x-y)*0.009-t*0.18)*7;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.025-t*0.5)*6 + Math.cos(sy*0.02+t*0.4)*5;
  const w2y = Math.cos(sy*0.028+t*0.45)*6 + Math.sin(sx*0.022-t*0.35)*5;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*110, 80+Math.cos(t*0.4)*55, 0.075, 2.1, 1.0],
    [320+Math.cos(t*0.5)*105, 160+Math.sin(t*0.7)*55, 0.095, 1.8, 0.9],
    [240+Math.sin(t*0.3+2)*145, 120+Math.cos(t*0.5+1)*95, 0.055, 2.4, 1.1],
    [120+Math.cos(t*0.8+1)*85, 180+Math.sin(t*0.6+3)*65, 0.11, 1.6, 0.85],
    [360+Math.sin(t*0.4+4)*95, 60+Math.cos(t*0.9+2)*75, 0.065, 2.7, 1.05],
    [240+Math.cos(t*0.35+5)*125, 200+Math.sin(t*0.55)*85, 0.085, 2.0, 0.95],
    [80+Math.sin(t*0.65+3)*70, 40+Math.cos(t*0.75+1)*50, 0.13, 1.4, 0.8],
    [400+Math.cos(t*0.45+2)*60, 200+Math.sin(t*0.85+4)*55, 0.07, 2.2, 1.15]
  ];
  let aS=0, iS=0, cross=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((fx-sX)**2 + (fy-sY)**2);
    const a = Math.sin(d*f - t*sp);
    const i = Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    aS += a*w; iS += i*w; cross += a*i*0.3*w;
  }
  const n = src.length;
  const act = aS/n, inh = iS/n, crs = cross/n;
  const bg = (Math.sin(fx*0.035+fy*0.022+t*0.9) + Math.sin(fx*0.028-fy*0.038+t*1.2) + Math.sin(fx*0.018+fy*0.045-t*0.7))/3;
  const dist = Math.sqrt((fx-cx)**2 + (fy-cy)**2), ang = Math.atan2(fy-cy, fx-cx);
  const spiral = (Math.sin(dist*0.045-ang*3.5-t*1.6) + Math.sin(dist*0.035+ang*4.5-t*1.3) + Math.sin(dist*0.06-ang*2-t*2.1))*0.3;
  const vortex = Math.sin(ang*6 + dist*0.03 - t*2)*Math.exp(-dist*0.005)*0.4;
  const lap = Math.sin(fx*0.16)*Math.sin(fy*0.16) + Math.sin(fx*0.11+t*0.7)*Math.sin(fy*0.13-t*0.5);
  const cell = Math.tanh(lap*1.8)*0.25;
  const wave = Math.sin((fx*0.08+fy*0.06-t*1.5))*Math.sin((fx*0.05-fy*0.09+t*1.2))*0.2;
  const reaction = Math.tanh((act - inh*0.65 + bg*0.25 + spiral + vortex + wave + crs*0.4)*2.0);
  const detail = Math.sin(fx*0.3+fy*0.25+t*3)*0.08*reaction;
  const blend = reaction*0.7 + cell*0.2 + detail;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[12,42,88],[18,78,112],[25,128,135],[60,165,130],
    [140,195,110],[210,195,70],[235,160,55],[220,110,60],[185,65,70],
    [130,35,65],[75,18,55],[35,12,48],[5,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.82 + Math.sin(reaction*Math.PI)*0.18;
  const edge = Math.abs(reaction)>0.65 ? 1.0 + (Math.abs(reaction)-0.65)*0.6 : 1.0;
  const glow = Math.max(0, reaction*0.15);
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + glow*80)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + glow*60)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + glow*40)|0)
  ];
}
